import zipfile
out='/root/safety_audit_brief_final.hwpx'
with zipfile.ZipFile(out) as z:
    bad=[]
    for name in z.namelist():
        data=z.read(name)
        try:
            text=data.decode('utf-8')
        except Exception:
            continue
        if '{{' in text:
            i=text.index('{{')
            j=text.find('}}', i)
            bad.append((name, text[i:j+2] if j!=-1 else text[i:i+40]))
    if bad:
        print('PLACEHOLDERS FOUND:')
        for n,s in bad:
            print(n, s)
    else:
        print('No placeholders found')
