python3 - <<'PY'
import zipfile, re
out='/root/safety_audit_brief_final.hwpx'
with zipfile.ZipFile(out) as z:
    any_dash=False
    any_dot=False
    for name in z.namelist():
        try:
            text=z.read(name).decode('utf-8')
        except Exception:
            continue
        dash=re.findall(r'\d{4}-\d{2}-\d{2}', text)
        dot=re.findall(r'\d{4}\.\d{2}\.\d{2}', text)
        if dash:
            any_dash=True
            print(f'WARNING: YYYY-MM-DD dates still in {name}: {dash}')
        if dot:
            any_dot=True
            print(f'OK: YYYY.MM.DD dates in {name}: {dot}')
    if not any_dot:
        print('WARNING: No dot-format dates found')
PY

python3 - <<'PY'
import zipfile
out='/root/safety_audit_brief_final.hwpx'
notes=['즉시조치','계획보완','모니터링']
with zipfile.ZipFile(out) as z:
    found=set()
    for name in z.namelist():
        try:
            text=z.read(name).decode('utf-8')
        except Exception:
            continue
        for note in notes:
            if note in text:
                found.add(note)
                print(f'Found severity note: {note} in {name}')
    if not found:
        print('WARNING: No severity notes found in any XML')
PY

